#!/usr/bin/env node
// The Claude Code status line in Node: what the bash one generated by
// electron/utils/statusline.ts does, for Windows, where bash, jq, awk and
// `stat -f/-c` are not there. Configured on win32 only; the bash script stays
// what macOS and Linux run, and remains the reference.
//
// It renders the same line and writes the same files the Usage page reads:
// ~/.dorothy/rate-limits.json (the `rate_limits` object as Claude Code sent
// it, for account 1), each account's counter in ~/.dorothy/rate-limits.d,
// and ~/.dorothy/token-stats.json (one entry per session, with its provider
// and account), the last under the same mkdir lock, written beside itself
// and renamed over.
//
// Where it differs on purpose: the git-branch cache file name replaces `\`
// and `:` as well as `/`, which a Windows file name cannot hold; a
// `rate_limits` that is a string is written as a JSON string, where jq's
// tostring writes it bare and the files it lands in stop being JSON.

import { execFileSync } from 'node:child_process';
import { randomBytes } from 'node:crypto';
import * as fs from 'node:fs';
import * as os from 'node:os';
import * as path from 'node:path';

const DATA_DIR = path.join(os.homedir(), '.dorothy');

function readStdin() {
  return new Promise(resolve => {
    const chunks = [];
    process.stdin.on('data', c => chunks.push(c));
    process.stdin.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')));
    process.stdin.on('error', () => resolve(''));
  });
}

const sleepSync = ms => Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0, ms);

/** jq `a // b`: b when a is null or false (or absent). */
const or = (value, fallback) => (value === undefined || value === null || value === false ? fallback : value);
/** jq `.a.b`: null through null, and an error, as jq raises one, on anything else that is not an object. */
function at(input, ...keys) {
  let current = input;
  for (const key of keys) {
    if (current === null || current === undefined) return null;
    if (typeof current !== 'object' || Array.isArray(current)) throw new Error('jq: cannot index');
    current = Object.prototype.hasOwnProperty.call(current, key) ? current[key] : null;
  }
  return current ?? null;
}

/**
 * jq `.a.b // fallback` in the one pass: the fallback when the path gives
 * null or false, and also when it cannot be indexed (a `model` that is a
 * string), since `//` swallows an error on its left side. Field by field: a
 * field of an unexpected shape costs that field alone.
 */
function alt(input, keys, fallback) {
  try {
    return or(at(input, ...keys), fallback);
  } catch {
    return fallback;
  }
}

/** jq @tsv of one value: strings escaped, numbers and booleans as jq prints them. */
function tsv(value) {
  const text = typeof value === 'string' ? value : JSON.stringify(value);
  return text.replace(/\\/g, '\\\\').replace(/\t/g, '\\t').replace(/\n/g, '\\n').replace(/\r/g, '\\r');
}

/**
 * The one jq pass of the bash script, and its `IFS=$'\t' read -r` into
 * fourteen names: a tab is IFS whitespace, so runs of tabs are one separator
 * and empty fields vanish, shifting the rest, exactly as bash reads them.
 */
function fields(text) {
  let line = '';
  try {
    const input = JSON.parse(text);
    const values = [
      alt(input, ['session_id'], ''),
      alt(input, ['context_window', 'total_input_tokens'], 0),
      alt(input, ['context_window', 'total_output_tokens'], 0),
      alt(input, ['cost', 'total_cost_usd'], 0),
      alt(input, ['model', 'model_id'], alt(input, ['model', 'display_name'], 'unknown')),
      alt(input, ['rate_limits', 'five_hour', 'used_percentage'], 0),
      alt(input, ['rate_limits', 'seven_day', 'used_percentage'], 0),
      alt(input, ['model', 'display_name'], '...'),
      alt(input, ['context_window', 'used_percentage'], 0),
      alt(input, ['context_window', 'context_window_size'], 200000),
      alt(input, ['cost', 'total_duration_ms'], 0),
      alt(input, ['cost', 'total_lines_added'], 0),
      alt(input, ['cost', 'total_lines_removed'], 0),
    ];
    // @tsv takes strings, numbers and booleans: an object or an array is an
    // error, and the whole pass gives nothing, as `2>/dev/null || true` leaves it.
    if (values.some(value => value !== null && typeof value === 'object')) throw new Error('jq: not valid in a tsv row');
    // `(.rate_limits // empty) | tostring`, as compact JSON. A `rate_limits`
    // that is a string stays a JSON string here, where jq's tostring writes it
    // bare and the files it lands in stop being JSON.
    const rateLimits = alt(input, ['rate_limits'], null);
    if (rateLimits !== null) values.push(JSON.stringify(rateLimits));
    line = values.map(tsv).join('\t');
  } catch {
    line = '';
  }
  const parts = line.replace(/^\t+|\t+$/g, '').split(/\t+/).filter(p => p !== '');
  const names = ['SESSION_ID', 'T_IN', 'T_OUT', 'T_COST', 'T_MODEL', 'PCT_5H', 'PCT_7D', 'MODEL', 'RAW_PCT_RAW',
    'CTX_MAX', 'DURATION_MS', 'LINES_ADDED', 'LINES_REMOVED', 'RATE_LIMITS'];
  const out = {};
  names.forEach((name, i) => {
    out[name] = i < names.length - 1 ? (parts[i] ?? '') : parts.slice(i).join('\t');
  });
  const defaults = { T_IN: '0', T_OUT: '0', T_COST: '0', T_MODEL: 'unknown', PCT_5H: '0', PCT_7D: '0', MODEL: '...',
    RAW_PCT_RAW: '0', CTX_MAX: '200000', DURATION_MS: '0', LINES_ADDED: '0', LINES_REMOVED: '0' };
  for (const [name, value] of Object.entries(defaults)) if (out[name] === '') out[name] = value;
  return out;
}

/** awk's reading of a string as a number: its leading numeric prefix, else 0. */
function awkNum(text) {
  const m = /^\s*[-+]?(\d+\.?\d*|\.\d+)([eE][-+]?\d+)?/.exec(String(text));
  return m ? Number(m[0]) : 0;
}
const looksNumeric = text => /^\s*[-+]?(\d+\.?\d*|\.\d+)([eE][-+]?\d+)?\s*$/.test(String(text));
/** awk `a > 100`: numeric when a looks like a number, else a string comparison with "100". */
const awkGreater100 = a => (looksNumeric(a) ? awkNum(a) > 100 : String(a) > '100');

/** printf "%.Nf": correct rounding of the double, ties to even as C does. */
function cFixed(x, digits) {
  const exact = x.toFixed(20);
  const m = new RegExp(`^(-?\\d+)\\.(\\d{${digits}})5(0*)$`).exec(exact);
  if (m) {
    const scaled = BigInt(m[1] + m[2]);
    const abs = scaled < 0n ? -scaled : scaled;
    const rounded = abs % 2n === 0n ? scaled : scaled + (scaled < 0n ? -1n : 1n);
    const s = (rounded < 0n ? -rounded : rounded).toString().padStart(digits + 1, '0');
    const sign = rounded < 0n || (rounded === 0n && x < 0) ? '-' : '';
    return digits === 0 ? `${sign}${s}` : `${sign}${s.slice(0, -digits)}.${s.slice(-digits)}`;
  }
  return x.toFixed(digits);
}

/** bash `$(( a ))` integer, or the script's `set -e` exit when it is not one. */
function bashInt(text) {
  if (!/^\s*-?\d+\s*$/.test(String(text))) throw new BashArithmeticError();
  return Number.parseInt(text, 10);
}
class BashArithmeticError extends Error {}

/**
 * Which Claude account this CLI runs on, as Tars launched it:
 * `${TARS_CLAUDE_ACCOUNT-default}`, unset meaning account 1 and an empty name
 * staying empty. Only `default` and `acct-` plus six hex digits name one: any
 * other would become a path, and writes no counter at all.
 */
const ACCOUNT = process.env.TARS_CLAUDE_ACCOUNT ?? 'default';
const ACCOUNT_NAME = /^(default|acct-[0-9a-f]{6})$/;

/**
 * The bash script's rate limits: rate-limits.json, which the Usage page reads,
 * for account 1 alone, and every account's own counter,
 * rate-limits.d/<account>.json, written beside itself and renamed over. A
 * render with no rate limits yet leaves both as they are.
 */
function writeRateLimits(rateLimits) {
  if (rateLimits === '' || rateLimits === 'null') return;
  if (!ACCOUNT_NAME.test(ACCOUNT)) return;
  if (ACCOUNT === 'default') {
    try {
      fs.writeFileSync(path.join(DATA_DIR, 'rate-limits.json'), `${rateLimits}\n`);
    } catch {
      // echo ... > file 2>/dev/null || true
    }
  }
  const dir = path.join(DATA_DIR, 'rate-limits.d');
  try { fs.mkdirSync(dir, { recursive: true }); } catch { /* mkdir -p ... || true */ }
  const tmp = path.join(dir, `.${ACCOUNT}.${process.pid}.tmp`);
  try {
    fs.writeFileSync(tmp, `{"updatedAt":${Math.floor(Date.now() / 1000)},"rate_limits":${rateLimits}}\n`);
    if (!renameOver(tmp, path.join(dir, `${ACCOUNT}.json`))) fs.rmSync(tmp, { force: true });
  } catch {
    try { fs.rmSync(tmp, { force: true }); } catch { /* rm -f */ }
  }
}

function localDate() {
  const d = new Date();
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
}

/** Past this many seconds a lock is taken for its holder's, dead (LOCK_STALE_AFTER). */
const LOCK_STALE_AFTER = 5;

/**
 * The token-stats lock of the bash script (upstream #216, #232): a folder
 * holding its owner's token, which a render removes only when it is its own.
 * Taken with mkdir, 20 tries 50 ms apart. A lock over 5 s old was left by a
 * render that died holding it, and is taken over by one render at a time
 * (the takeover folder), and only while it is still the lock that was judged
 * dead: removed and made again by whoever passed, it let two renders that had
 * both judged it dead remove the one the first had just taken.
 */
function tokenStatsLock(lockDir) {
  const ownerFile = path.join(lockDir, 'owner');
  const token = `${process.pid}.${randomBytes(4).toString('hex')}`;
  // mkdir "$LOCK_DIR" && printf '%s' "$LOCK_TOKEN" > "$LOCK_OWNER"
  const take = () => {
    try {
      fs.mkdirSync(lockDir);
      fs.writeFileSync(ownerFile, token);
      return true;
    } catch {
      return false;
    }
  };
  const owner = () => { try { return fs.readFileSync(ownerFile, 'utf8'); } catch { return ''; } };
  // $(date +%s) - $(stat ... || echo 0), in whole seconds: one gone reads as very old.
  const age = dir => { try { return Math.floor(Date.now() / 1000) - Math.floor(fs.statSync(dir).mtimeMs / 1000); } catch { return Infinity; } };
  const rmdir = dir => { try { fs.rmdirSync(dir); } catch { /* 2>/dev/null || true */ } };

  const acquire = () => {
    for (let i = 0; i < 20; i++) {
      if (take()) return true;
      sleepSync(50);
    }
    // [ -d "$LOCK_DIR" ]: no lock at all is no takeover either.
    if (!fs.existsSync(lockDir)) return false;
    const staleOwner = owner();
    if (!(age(lockDir) > LOCK_STALE_AFTER)) return false;
    const takeover = `${lockDir}.takeover`;
    // One left by a render killed while taking a lock over would stop every takeover after it.
    if (fs.existsSync(takeover) && age(takeover) > LOCK_STALE_AFTER) rmdir(takeover);
    try {
      fs.mkdirSync(takeover);
    } catch {
      return false;
    }
    try {
      if (owner() === staleOwner && age(lockDir) > LOCK_STALE_AFTER) {
        fs.rmSync(ownerFile, { force: true });
        rmdir(lockDir);
      }
      return take();
    } finally {
      rmdir(takeover);
    }
  };

  // Its own only: a render slow past 5 s, whose lock had been taken over,
  // removed the new holder's as it released. Called once, when the write is
  // done, and not again at exit: by then another render may hold the lock.
  const release = () => {
    if (owner() !== token) return;
    try { fs.rmSync(ownerFile, { force: true }); } catch { /* rm -f */ }
    rmdir(lockDir);
  };

  return { acquire, release };
}

/** mv over the file; on Windows a reader holding it open can make that fail for a moment. */
function renameOver(from, to) {
  for (let i = 0; i < 5; i++) {
    try {
      fs.renameSync(from, to);
      return true;
    } catch (error) {
      if (process.platform !== 'win32' || !['EPERM', 'EBUSY', 'EACCES'].includes(error?.code)) return false;
      sleepSync(20);
    }
  }
  return false;
}

function writeTokenStats(f) {
  if (!f.SESSION_ID) return;
  const extra = awkGreater100(f.PCT_5H) || awkGreater100(f.PCT_7D);
  const lock = tokenStatsLock(path.join(DATA_DIR, 'token-stats.lock'));
  if (!lock.acquire()) return;
  try {
    const file = path.join(DATA_DIR, 'token-stats.json');
    let existing = '';
    try { existing = fs.readFileSync(file, 'utf8'); } catch { /* || true */ }
    let tin, tout, cost;
    try {
      // --argjson: each must be one JSON value, or jq fails and nothing is written.
      [tin, tout, cost] = [f.T_IN, f.T_OUT, f.T_COST].map(v => JSON.parse(v));
    } catch {
      return;
    }
    let stats;
    try { stats = JSON.parse(existing); } catch { stats = {}; }
    if (stats === null || typeof stats !== 'object' || Array.isArray(stats)) stats = {};
    stats[f.SESSION_ID] = {
      in: tin, out: tout, cost, model: f.T_MODEL, extra, date: localDate(), provider: process.env.CLAUDE_PROVIDER || 'claude',
      // `${TARS_CLAUDE_ACCOUNT:-}`: the session's account, empty for one that names none.
      account: process.env.TARS_CLAUDE_ACCOUNT || '',
    };
    const tmp = `${file}.tmp.${process.pid}`;
    try {
      fs.writeFileSync(tmp, `${JSON.stringify(stats)}\n`);
      if (!renameOver(tmp, file)) fs.rmSync(tmp, { force: true });
    } catch {
      try { fs.rmSync(tmp, { force: true }); } catch { /* rm -f */ }
    }
  } finally {
    lock.release();
  }
}

/**
 * The git to run: on Windows the first git.exe on the PATH, by its full path,
 * or null. This runs in the project's folder, and Node on Windows looks a bare
 * `git` up there before the PATH: a repository carrying a git.exe of its own
 * would have it run every 5 s (electron/platform/git-command.ts). Only plain
 * absolute entries: a relative one is the current folder again. No git on the
 * PATH: no branch. Elsewhere `git`, which no lookup finds in the current folder.
 */
function gitOnPath() {
  if (process.platform !== 'win32') return 'git';
  for (const raw of (process.env.PATH || '').split(';')) {
    const dir = raw.trim().replace(/^"(.*)"$/, '$1');
    if (!/^[a-z]:[\\/]/i.test(dir) || dir.slice(2).includes(':')) continue;
    const file = path.win32.join(dir, 'git.exe');
    try {
      if (fs.statSync(file).isFile()) return file;
    } catch {
      // not there
    }
  }
  return null;
}

function gitBranch() {
  const cacheDir = path.join(DATA_DIR, 'statusline-cache');
  try { fs.mkdirSync(cacheDir, { recursive: true, mode: 0o700 }); } catch { /* || true */ }
  try { fs.chmodSync(cacheDir, 0o700); } catch { /* || true */ }
  const cache = path.join(cacheDir, `git${process.cwd().replace(/[\\/:]/g, '_')}`);
  let branch = '?';
  try {
    const st = fs.lstatSync(cache);
    if (st.isFile() && (Date.now() - st.mtimeMs) / 1000 < 5) branch = fs.readFileSync(cache, 'utf8').replace(/\n+$/, '');
  } catch {
    // no cache yet
  }
  if (branch === '?') {
    try {
      const git = gitOnPath();
      if (!git) throw new Error('no git on the PATH');
      branch = execFileSync(git, ['rev-parse', '--abbrev-ref', 'HEAD'], { stdio: ['ignore', 'pipe', 'ignore'], windowsHide: true })
        .toString('utf8').replace(/\n+$/, '').replace(/\r$/, '');
      if (branch === '') branch = '?';
    } catch {
      branch = '?';
    }
    let isLink = false;
    try { isLink = fs.lstatSync(cache).isSymbolicLink(); } catch { /* absent */ }
    if (!isLink) {
      try { fs.writeFileSync(cache, `${branch}\n`); } catch { /* || true */ }
    }
  }
  return branch;
}

function formatDuration(ms) {
  const totalSec = Math.trunc(ms / 1000);
  const hours = Math.trunc(totalSec / 3600);
  const mins = Math.trunc((totalSec % 3600) / 60);
  if (hours > 0) return `${hours}h${mins}m`;
  if (mins > 0) return `${mins}m`;
  return `${totalSec}s`;
}

function formatTokens(tokens) {
  // `[ "$tokens" -ge ... ]` on something that is not an integer is false (and
  // an error on stderr): the value is printed as it is.
  if (!/^\s*-?\d+\s*$/.test(String(tokens))) return String(tokens);
  const n = Number.parseInt(tokens, 10);
  if (n >= 1000000) return `${cFixed(n / 1000000, 1)}M`;
  if (n >= 1000) return `${cFixed(n / 1000, 0)}k`;
  return String(tokens);
}

const RESET = '\x1b[0m';
const DIM = '\x1b[2m';
const BOLD = '\x1b[1m';
const GREEN = '\x1b[32m';
const YELLOW = '\x1b[33m';
const RED = '\x1b[31m';
const CYAN = '\x1b[36m';
const MAGENTA = '\x1b[35m';
const WHITE = '\x1b[37m';
const AUTOCOMPACT_BUFFER = 33000;

function render(f) {
  const rawPct = Math.trunc(awkNum(f.RAW_PCT_RAW));
  const ctxUsed = Math.trunc((rawPct * awkNum(f.CTX_MAX)) / 100);
  const ctxUsable = bashInt(f.CTX_MAX) - AUTOCOMPACT_BUFFER;
  if (ctxUsable === 0) throw new BashArithmeticError(); // awk: division by zero
  const ctxPct = Math.trunc((ctxUsed * 100) / ctxUsable);
  const branch = gitBranch();
  const duration = formatDuration(bashInt(f.DURATION_MS));
  const ctxUsedFmt = formatTokens(String(ctxUsed));
  const ctxUsableFmt = formatTokens(String(ctxUsable));
  const inFmt = formatTokens(f.T_IN);
  const outFmt = formatTokens(f.T_OUT);
  const ctxColor = ctxPct >= 80 ? RED : ctxPct >= 50 ? YELLOW : GREEN;
  let filled = Math.trunc(ctxPct / 10);
  if (filled > 10) filled = 10;
  const empty = 10 - filled;
  const bar = '▰'.repeat(Math.max(0, filled)) + '▱'.repeat(Math.max(0, empty));
  const sep = `${DIM} │ ${RESET}`;
  return `${CYAN}${BOLD}◆${RESET} ${WHITE}${BOLD}${f.MODEL}${RESET}${sep}`
    + `${ctxColor}ctx: ${ctxPct}% ${bar}${RESET} ${DIM}(${ctxUsedFmt}/${ctxUsableFmt})${RESET}${sep}`
    + `${MAGENTA}${branch}${RESET}${sep}`
    + `${DIM}${duration}${RESET}${sep}`
    + `${GREEN}+${f.LINES_ADDED}${RESET} ${RED}-${f.LINES_REMOVED}${RESET}${sep}`
    + `${DIM}↑${inFmt} ↓${outFmt}${RESET}\n`;
}

const f = fields(await readStdin());
writeRateLimits(f.RATE_LIMITS);
writeTokenStats(f);
let line = '';
let code = 0;
try {
  line = render(f);
} catch (error) {
  // The bash script runs under `set -e`: a value its arithmetic cannot take
  // ends it there, with nothing printed. Anything else is a bug: say so.
  if (!(error instanceof BashArithmeticError)) process.stderr.write(`statusline: ${error?.stack ?? error}\n`);
  code = error instanceof BashArithmeticError ? 2 : 1;
}
if (line) process.stdout.write(line, () => process.exit(code));
else process.exit(code);
